INSERT INTO `elenco` (`id`, `nombre`, `descripcion`, `adjunto`, `contacto`) VALUES
(8, 'EL ENJAMBRE', '<p><strong><span style=\"font-family: \'Helvetica\',\'sans-serif\'; mso-bidi-font-family: \'Segoe UI\'; color: #383d41;\">Ensamble Vocal de la&nbsp;Universidad Nacional de San Luis (UNSL) y el Instituto de Formaci&oacute;n Docente Continua - San Luis (IFDC-SL), con la direcci&oacute;n vocal de Yeka Ramos y la direcci&oacute;n esc&eacute;nica de Faviola Perroni.</span></strong></p>\r\n<p><span style=\"font-family: \'Helvetica\',\'sans-serif\'; mso-bidi-font-family: \'Segoe UI\'; color: #383d41; mso-bidi-font-weight: bold;\">El Enjambre se crea<strong>&nbsp;</strong></span><span style=\"font-family: \'Helvetica\',\'sans-serif\'; mso-bidi-font-family: \'Segoe UI\'; color: #383d41;\">en el a&ntilde;o 2020, con el objetivo de reivindicar los ritmos platenses, como la murga y el candombe, y hacer un repertorio de voces mixtas. Tras haber realizado diversas presentaciones en actos institucionales y producciones audiovisuales junto a UNSL TV, en diciembre de 2022 present&oacute; su primer espect&aacute;culo, en Comuna Club de la ciudad de San Luis.&nbsp;</span></p>\r\n<p><span style=\"font-family: \'Helvetica\',\'sans-serif\'; mso-bidi-font-family: \'Segoe UI\'; color: #383d41;\">En marzo de 2023 realiz&oacute; la Gira Interbarrial de carnaval, recorriendo los barrios Aeroferro, Jos&eacute; Hern&aacute;ndez, 1&ordm; de Mayo y Rep&uacute;blica. Enseguida fue invitado por el Concejo Deliberante de la ciudad de San Luis a compartir su m&uacute;sica en la Jornada por el D&iacute;a Internacional de la Mujer Trabajadora. Particip&oacute; del evento solidario La Llama Cultural en Estancia Grande; realiz&oacute; un concierto did&aacute;ctico para los barrios N&eacute;stor Kirchner; y -en junio- fue telonero del espect&aacute;culo de la murga mendocina La Buena Moza, en la Sala Hugo del Carril del Centro Cultural Puente Blanco.&nbsp;</span></p>', 'web.jpg', 'https://www.instagram.com/elenjambre.sl/'),
(9, 'LE MAQUINAL', '<p><strong><span style=\"font-family: \'Helvetica\',\'sans-serif\'; mso-bidi-font-family: \'Segoe UI\'; color: #383d41;\">Grupo de Teatro dirigido por la licenciada en Arte Dram&aacute;tico Marcela Aravena en la Universidad Nacional de San luis.&nbsp;</span></strong></p>\r\n<p><span style=\"font-family: \'Helvetica\',\'sans-serif\'; mso-bidi-font-family: \'Segoe UI\'; color: #383d41;\">Se conform&oacute; en el a&ntilde;o 2017, tras el suceso esc&eacute;nico&nbsp;<strong>&ldquo;Pantano Teatral&rdquo;</strong>&nbsp;y a partir del estreno de la obra&nbsp;<strong>&ldquo;Marathon&rdquo;</strong>&nbsp;de Ricardo Monti, con la cual particip&oacute; de la Gira Provincial del INT 2018; se present&oacute; en el Teatro Roma de San Rafael, Mendoza; particip&oacute; de la Fiesta Provincial del INT 2019 (seleccionada para el Encuentro Regional); y se despidi&oacute; en el V Festival Internacional de La Palabra en Escena.</span></p>\r\n<p><span style=\"font-family: \'Helvetica\',\'sans-serif\'; mso-bidi-font-family: \'Segoe UI\'; color: #383d41;\">En noviembre de ese a&ntilde;o, el grupo estren&oacute; su adaptaci&oacute;n del cl&aacute;sico de Moli&egrave;re&nbsp;<strong>&ldquo;El Burgu&eacute;s&rdquo;</strong>, con la que primero recorri&oacute; numerosas salas de la provincia de San Luis: Auditorio Mauricio L&oacute;pez, Hugo del Carril, Bertha Vidal de Battini, Durquesh, UNViMe y Santa Catalina; y luego, en 2022, sali&oacute; de gira por las provincias de Mendoza y C&oacute;rdoba. Con motivo de celebrar los 400 a&ntilde;os de Moli&egrave;re, en conjunto con distintas Alianzas Francesas, llev&oacute; funciones al Tau Cervantes de Bell Ville, al Teatro Selectro de ciudad de Mendoza, y -finalmente- al Pabell&oacute;n Argentina de la ciudad de C&oacute;rdoba.&nbsp;</span></p>\r\n<p><span style=\"font-family: \'Helvetica\',\'sans-serif\'; mso-bidi-font-family: \'Segoe UI\'; color: #383d41;\">En junio de 2023, Le Maquinal estren&oacute; su nueva producci&oacute;n&nbsp;<strong>\"Justo antes de la noche\"</strong>.</span></p>', '_GF_63201.jpg', 'https://linktr.ee/lemaquinalteatro');
