llcolor=\"#d6e3bc [1302]\">\r\n <v:textbox>\r\n  <![if !mso]>\r\n  <table cellpadding=0 cellspacing=0 width=\"100%\">\r\n   <tr>\r\n    <td><![endif]>\r\n    <div>\r\n    <p class=MsoNormal align=center style=\'text-align:center\'><b\r\n    style=\'mso-bidi-font-weight:normal\'><span lang=es style=\'font-size:14.0pt;\r\n    line-height:115%\'>GESTOS DEÍCTICOS<o:p></o:p></span></b></p>\r\n    </div>\r\n    <![if !mso]></td>\r\n   </tr>\r\n  </table>\r\n  <![endif]></v:textbox>\r\n <w:wrap type=\"square\"/>\r\n</v:shape><![endif]--><!-- [if !vml]--><img src=\"file:///C:/Users/MARIEE~1/AppData/Local/Temp/msohtmlclip1/02/clip_image001.gif\" alt=\"Cuadro de texto: GESTOS DE&Iacute;CTICOS\" width=\"217\" height=\"50\" align=\"left\" hspace=\"12\" vspace=\"5\" /><!--[endif]--></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: 150%; tab-stops: 67.5pt;\"><!-- [if gte vml 1]><v:shapetype\r\n id=\"_x0000_t67\" coordsize=\"21600,21600\" o:spt=\"67\" adj=\"16200,5400\" path=\"m0@0l@1@0@1,0@2,0@2@0,21600@0,10800,21600xe\">\r\n <v:stroke joinstyle=\"miter\"/>\r\n <v:formulas>\r\n  <v:f eqn=\"val #0\"/>\r\n  <v:f eqn=\"val #1\"/>\r\n  <v:f eqn=\"sum height 0 #1\"/>\r\n  <v:f eqn=\"sum 10800 0 #1\"/>\r\n  <v:f eqn=\"sum width 0 #0\"/>\r\n  <v:f eqn=\"prod @4 @3 10800\"/>\r\n  <v:f eqn=\"sum width 0 @5\"/>\r\n </v:formulas>\r\n <v:path o:connecttype=\"custom\" o:connectlocs=\"10800,0;0,@0;10800,21600;21600,@0\"\r\n  o:connectangles=\"270,180,90,0\" textboxrect=\"@1,0,@2,@6\"/>\r\n <v:handles>\r\n  <v:h position=\"#1,#0\" xrange=\"0,10800\" yrange=\"0,21600\"/>\r\n </v:handles>\r\n</v:shapetype><v:shape id=\"Flecha_x0020_abajo_x0020_5\" o:spid=\"_x0000_s1026\"\r\n type=\"#_x0000_t67\" style=\'position:absolute;left:0;text-align:left;\r\n margin-left:190.2pt;margin-top:23.4pt;width:35.25pt;height:31.5pt;z-index:251659264;\r\n visibility:visible;mso-wrap-style:square;mso-width-percent:0;\r\n mso-height-percent:0;mso-wrap-distance-left:9pt;mso-wrap-distance-top:0;\r