INSERT INTO `proyectos-gestor` (`id`, `titulo`, `duracion`, `unidadAcademica`, `objetivosGenerales`, `objetivosEspecificos`, `conceptualizacionProblema`, `situacionProblematicaContextual`, `marcoTeorico`, `proyectosEjecutados`, `integracionDisciplinar`, `locacionTerritorial`, `adjunto`, `caracterizacionSomera`, `politicasPublicasExistentes`, `politicasPublicasConOrg`, `ods`, `cronograma`, `coherenciaInterna`, `propuestasEquipoExt`, `propuestasCursos`, `sostenimiento`, `carreras`, `disciplinas`, `problematica`, `justificacion`, `origen`, `aporteUniversidad`, `objetivoAprendizaje`, `localizacion`, `publico`, `cronogramaProyecto`, `cronogramaEstudiantes`, `periodo`, `estrategiasSupervision`, `evaluacionAprendizaje`, `evaluacionResultado`, `avalAdjunto`, `proyecto-tipo`, `estado`, `idIdeaProyecto`, `idusuario`) VALUES
(176, 'FORTALECIMIENTO DE LAS CIENCIAS NATURALES EN EL NIVEL PRIMARIO', '12 meses', 'FQBF', '<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal; mso-layout-grid-align: none; text-autospace: none;\"><span lang=\"ES\" style=\"font-family: \'Verdana\',sans-serif; mso-bidi-font-family: Verdana; mso-ansi-language: ES;\">Promover el aprendizaje por indagaci&oacute;n y el pensamiento cr&iacute;tico en las ciencias naturales a trav&eacute;s de la experimentaci&oacute;n de laboratorio </span></p>', '<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">Dise&ntilde;ar y producir material did&aacute;ctico de experiencias de ciencias naturales en el marco del aprendizaje por indagaci&oacute;n para estudiantes de nivel primario</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">&nbsp;Propiciar la participaci&oacute;n de los estudiantes y maestros de las escuelas en al menos dos experiencias de laboratorio durante el a&ntilde;o de la mano de docentes, investigadores y estudiantes de la UNSL.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">&nbsp;Impulsar la participaci&oacute;n activa de los estudiantes universitarios en el dise&ntilde;o y desarrollo de talleres experimentales</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"mso-bidi-font-family: \'Adobe Garamond Pro\'; color: black;\">En el presente proyecto se pretende abordar las principales dificultades para llevar las ciencias naturales a las aulas de Educaci&oacute;n primaria, entre las que podemos mencionar</span><span lang=\"es\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">: </span><span lang=\"es\" style=\"mso-bidi-font-family: \'Adobe Garamond Pro\'; color: black;\">La dificultad de realizar experiencias de Cs. Naturales por la necesidad de recursos espec&iacute;ficos que no est&aacute;n a su alcance, falta de formaci&oacute;n para el aprovechamiento de las herramientas disponibles, <span style=\"mso-spacerun: yes;\">&nbsp;</span>el poco inter&eacute;s que las ciencias despiertan en los ni&ntilde;os y ni&ntilde;as; <span style=\"mso-spacerun: yes;\">&nbsp;</span>la poca adecuaci&oacute;n de las ciencias a este nivel educativo y</span> <span lang=\"es\" style=\"mso-bidi-font-family: \'Adobe Garamond Pro\'; color: black;\">la falta de formaci&oacute;n disciplinar y did&aacute;ctica.</span><span lang=\"es\"> Se pretende facilitar el aprendizaje de contenidos en ciencias naturales b&aacute;sicos en el nivel primario, como as&iacute; <span style=\"mso-spacerun: yes;\">&nbsp;</span>tambi&eacute;n procedimientos, actitudes, valores propios del trabajo cient&iacute;fico, es decir que sean capaces de utilizar todas sus potencialidades para predecir y explicar determinados fen&oacute;menos, disfrutando de la ciencia.</span></p>', '<p class=\"MsoNormal\"><span lang=\"es\" style=\"font-size: 14.0pt; line-height: 115%;\">ESCUELA N&deg; 228 &ldquo;GOBERNADOR JUAN SA&Aacute;&rdquo;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; text-indent: 35.4pt; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\">La Escuela N&deg; 228 se encuentra ubicada en la zona sur de la Ciudad de San Luis sobre la Ruta Nacional N&deg; 146 en el km 6, extendiendo su zona de influencia por los Barrios: San Jos&eacute;, Estrella Del Sur, Solidaridad, Uni&oacute;n y 400 Viviendas Sur. Adem&aacute;s de albergar a los alumnos de la zona rural.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\">Actualmente cuenta con los niveles Inicial Primario y Secundario, con una matr&iacute;cula de 22 en Nivel Inicial; 136 en Primario y 106 en Secundario. -</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; text-indent: 35.4pt; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\">El contexto socio econ&oacute;mico en que se encuentra ubicada la Escuela en general presenta caracter&iacute;sticas de zona muy carenciada, con marcadas dificultades econ&oacute;micas. -</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\"><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>En cuanto a la actividad econ&oacute;mica de la zona, se caracteriza por la producci&oacute;n de ladrillos y algunas huertas familiares, entre la poblaci&oacute;n cercana a la escuela cabe destacar la presencia de familias de origen Boliviano.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\"><span style=\"mso-tab-count: 2;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Las edades de los alumnos van de los 4 a&ntilde;os en Nivel Inicial hasta los 18/19 en Nivel Secundario. Es importante se&ntilde;alar que la Escuela cuenta con Secundario generativo rural completo (6 a&ntilde;os), con orientaci&oacute;n en agro y ambiente. -</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\"><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Debido a la numerosa poblaci&oacute;n de la zona se hace necesaria la ampliaci&oacute;n del edificio escolar, la que se est&aacute; gestionando ya que contamos con espacio suficiente como para una mayor comodidad y como consecuencia mejorar el servicio que hoy se brinda.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\"><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Se ha detectado, adem&aacute;s, la dificultad que se presenta en cuanto a los cuidados de la salud ya que toda la zona cuenta con un CAPS (Centro de Atenci&oacute;n Primaria de la Salud) en el Barrio Estrella del Sur que debido al incremento de poblaci&oacute;n de la zona no puede atender a toda la poblaci&oacute;n.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\"><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Desde la Instituci&oacute;n escolar se trabaja para concientizar a la poblaci&oacute;n escolar sobre los cuidados de la salud y la importancia de tener conocimientos b&aacute;sicos de primeros auxilios. -</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"es\" style=\"font-size: 12.0pt;\"><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>En lo que a personal se refiere; cuenta con lo necesario en lo que es Nivel Inicial y Primario; no as&iacute; en lo que es Secundario en donde los alumnos est&aacute;n recibiendo solo 2 horas de clases diarias en el Ciclo B&aacute;sico y 2 en el Orientado, cabe se&ntilde;alar tambi&eacute;n que el secundario si bien funciona en el mismo edificio, no depende de la misma conducci&oacute;n ya que al ser generativo rural tiene profesores designados desde la ULP, a cargo de la figura del Coordinador que es la autoridad del nivel. &ndash;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">La escuela N&ordm; 164 Maestros Puntanos (</span><span lang=\"es\" style=\"font-family: \'Segoe UI\',sans-serif; color: black;\">ELEODORO LOBOS - SAN LUIS), Eleodoro Lobos Coronel Pringles San Luis), es una escuela unipersonal, con plurigrado y una matr&iacute;cula aproximada de 20 estudiantes que comparten espacio f&iacute;sico, donde los estudiantes m&aacute;s grandes ayudan a los m&aacute;s peque&ntilde;os. Consta de una sola ordenanza quien se encarga de las actividades correspondientes y brinda la copa de leche. La mayor&iacute;a de los estudiantes viven alejados de la escuela (aproximadamente 10-15 km). </span><span lang=\"ES\" style=\"mso-ansi-language: ES;\">La mayor&iacute;a de las familias tienen trabajo como empleados en estancias. La escuela no cuenta con transporte para los estudiantes</span></p>', '<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">Que &ldquo;todo&rdquo; es Qu&iacute;mica, ya es una idea com&uacute;n en la ense&ntilde;anza de las ciencias natuales. Pero, &iquest;se ense&ntilde;a algo de Qu&iacute;mica a los m&aacute;s peque&ntilde;os? No tenemos m&aacute;s que echar un vistazo al curr&iacute;culo de Educaci&oacute;n Primaria. Desde nuestro punto de vista, qu&eacute; ense&ntilde;ar al alumnado de Primaria sobre estos contenidos b&aacute;sicos es un problema profesional para los docentes (actuales y futuros). Facilitar el aprendizaje de estos contenidos qu&iacute;micos b&aacute;sicos no es nada sencillo. Es decir, por ejemplo, &iquest;qu&eacute; idea de reacci&oacute;n qu&iacute;mica pretendemos que aprendan en Primaria? o &iquest;en qu&eacute; deben fijarse para diferenciar reacciones qu&iacute;micas y mezclas? Entendemos que para hacer propuestas sobre dichos interrogantes hay que tener un dominio espec&iacute;fico (profesionalizado) de los contenidos qu&iacute;micos b&aacute;sicos. No el dominio que necesita un futuro qu&iacute;mico, sino el dominio que necesita alguien cuyo inter&eacute;s es facilitar que otros aprendan.<span style=\"mso-spacerun: yes;\">&nbsp; </span>Pero para muchos maestros /as, su mayor preocupaci&oacute;n es &iquest;c&oacute;mo ense&ntilde;ar esos contenidos? Sin duda hay muchas maneras de hacerlo. Hemos visto a maestros excesivamente dependientes del libro de texto y a alumnos leyendo y subrayando el libro. Tambi&eacute;n hemos visto, menos frecuentemente, realizar actividades pr&aacute;cticas en las que los alumnos deb&iacute;an seguir una &ldquo;receta&rdquo; establecida. Pero no parece que ninguna de esas opciones pueda contribuir de forma significativa al desarrollo de la competencia cient&iacute;fica de los alumnos y que a su vez disfruten con la ciencia.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal; mso-layout-grid-align: none; text-autospace: none;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">El desarrollo del presente proyecto generar&aacute; una experiencia enriquecedora para que los docentes de las escuelas se inspiren y puedan incorporar algunas actividades de laboratorio en qu&iacute;mica en sus planificaciones</span></p>', '<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">El presente Proyecto se presenta como una consolidaci&oacute;n de actividades de extensi&oacute;n que se vienen realizando en la tem&aacute;tica desde el a&ntilde;o 2013 (Semana Nacional de la Ciencia y la Tecnolog&iacute;a, Tecn&oacute;polis - VocAr-CONICET, feria internacional del libro de Buenos Aires, Qu&iacute;micos a la escuela, Proyecto 14945 descubriendo cient&iacute;ficos&nbsp;EU61-UNSL14945). Este &uacute;ltimo proyecto financiado con a trav&eacute;s de la Secretaria de pol&iacute;tica Universitarias, con la direcci&oacute;n de la Dra Miryan Villegas, desarrollo varios talleres, debido a su conformaci&oacute;n interdisciplinar. El taller &ldquo;s&oacute;lido liquido&rdquo; estuvo cargo del Dr. Luis Escudero, actividad que demostr&oacute; gran inter&eacute;s en las escuelas visitadas</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">En cada uno de los encuentros planteados observamos que, tanto directivos como docentes y resto del personal de cada instituci&oacute;n, demostraron profundo inter&eacute;s por las actividades, con una excelente predisposici&oacute;n para que pudi&eacute;semos brindar los talleres con total libertad y comodidad (ello aplicable a cada una de las escuelas que fuimos); en todo momento contamos con la participaci&oacute;n de todos ellos, quienes tambi&eacute;n lo hicieron activamente en cada propuesta. Siempre nos destacaron la importancia de nuestra presencia en escuelas distantes de la ciudad capital de la provincia, y de los efectos que ello en los ni&ntilde;os generaba.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">Con respecto a ciertas actividades planteadas, algunos docentes manifestaron que hab&iacute;an abordado tem&aacute;ticas similares con resultados diversos: por ejemplo, la producci&oacute;n de alcohol en gel aromatizado con productos naturales, otros hab&iacute;an intentado desarrollar &ldquo;slime&rdquo;, pero con resultados negativos para ambos casos. Precisamente, uno de los talleres planteados en este proyecto es referente a la elaboraci&oacute;n del &ldquo;slime&rdquo; y merced a su realizaci&oacute;n, tales docentes han podido mejorar y optimizar el procedimiento para su replicaci&oacute;n futura con &eacute;xito. Frente a ello, se destaca la importancia de una interacci&oacute;n para cubrir falencias o necesidades que motiven o que hayan motivado la no obtenci&oacute;n de los resultados experimentales deseados.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">Algunas escuelas tienen dentro de sus pertenencias, equipamiento de laboratorio brindado por la Naci&oacute;n, los que a&uacute;n se encontraban embalados y guardados bajo llave en armarios desde que les fuera entregado para evitar su deterioro y exposici&oacute;n, ya que no eran usados debido a la falta de capacitaci&oacute;n y/o a la carencia de docentes espec&iacute;ficos en la tem&aacute;tica; esta situaci&oacute;n nos permiti&oacute; brindar un asesoramiento al personal y demostrar la utilidad de estos.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">Hemos encontrado altas disparidades desde el punto de vista social, intelectual y educativo en el alumnado de las distintas escuelas con las que estamos trabajando; sin embargo, y pese a ello, cuando se plantearon las actividades relacionando la vida cotidiana con los temas espec&iacute;ficos de cada taller, se observ&oacute; una participaci&oacute;n activa por parte de los estudiantes.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: ES;\">Se debe destacar que, en d&iacute;as previos a nuestra ida programada a la escuela, los docentes respectivos mantuvieron conversaciones con los ni&ntilde;os sobre nuestra visita y acerca de los contenidos de los talleres a desarrollar. No obstante, de conocer previamente los contenidos, los talleres generaron una gran motivaci&oacute;n en docentes y estudiantes, lo que manifest&oacute; la necesidad de desarrollar actividades experimentales en el aula. Asimismo, al finalizar nuestra labor y emprender nuestro viaje de regreso, tuvimos c&aacute;lidas y afectuosas despedidas con todos ellos, planteando los directivos y docentes la necesidad de pr&oacute;ximos encuentros, de que nuestra visita no sea la &uacute;ltima, de que a la pr&oacute;xima vez que vayamos nos agasajar&aacute;n esper&aacute;ndonos con el almuerzo, todo ello en concordancia con los pedidos de los ni&ntilde;os para que volvamos, que no los olvidemos, de que vayamos a sus casas y que conozcamos a sus padres, hermanos, primos, amigos, etc.; vivencias que permanecer&aacute;n imborrables en nuestras memorias y que nos permiten agradecer la posibilidad que tenemos de efectuar tareas en el campo de la extensi&oacute;n universitaria.</span></p>', '<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 12.0pt; font-family: \'Calibri Light\',sans-serif; mso-ascii-theme-font: major-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: major-latin; mso-bidi-theme-font: major-latin; color: black; mso-ansi-language: ES;\">El proyecto est&aacute; formado por un director cuya especialidad es la qu&iacute;mica (&aacute;rea de qu&iacute;mica Anal&iacute;tica), una codirectora con formaci&oacute;n doctoral en biolog&iacute;a y qu&iacute;mica (&Aacute;rea &nbsp;de Qu&iacute;mica&nbsp; Org&aacute;nica) y tres docentes integrantes de formaci&oacute;n similar; tambi&eacute;n participaran estudiantes universitarios de la carrera Lic. en Qu&iacute;mica.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; line-height: normal;\"><span lang=\"ES\" style=\"font-size: 12.0pt; font-family: \'Calibri Light\',sans-serif; mso-ascii-theme-font: major-latin; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-theme-font: major-latin; mso-bidi-theme-font: major-latin; color: black; mso-ansi-language: ES;\">El abordaje interdisciplinar qu&iacute;mico y biol&oacute;gico permitir&aacute; contribuir en la formaci&oacute;n de los estudiantes en el campo de las ciencias naturales</span></p>', '<p class=\"MsoNormal\" style=\"margin-top: 22.5pt; line-height: 16.5pt; mso-outline-level: 2;\"><strong><span lang=\"es\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black;\">ESCUELA N&ordm; 228 GOBERNADOR JUAN SAA</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; line-height: normal;\"><span lang=\"es\" style=\"font-size: 10.0pt; font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black;\">https://www.google.com/maps/dir/San+Luis/-33.3374662,-66.3624601/@-33.3186318,-66.3610814,14z/data=!3m1!4b1!4m8!4m7!1m5!1m1!1s0x95d43954196ca6cd:0x7fc2e3b4d49ecc83!2m2!1d-66.3377522!2d-33.3017267!1m0</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-top: 22.5pt; line-height: 16.5pt; mso-outline-level: 2;\"><strong><span lang=\"es\" style=\"font-size: 10pt; font-family: \'Segoe UI\', sans-serif;\">ESCUELA N&ordm; 164 MAESTROS PUNTANOS</span></strong></p>\r\n<p><span lang=\"es\" style=\"font-size: 10.0pt; line-height: 115%; font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\"><a href=\"https://www.google.com/maps/dir/San+Luis/-33.391051,-66.0152098/@-33.2242713,-66.2845622,11z/data=!3m1!4b1!4m8!4m7!1m5!1m1!1s0x95d43954196ca6cd:0x7fc2e3b4d49ecc83!2m2!1d-66.3377522!2d-33.3017267!1m0\"><span style=\"font-family: \'Segoe UI\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: blue;\">https://www.google.com/maps/dir/San+Luis/-33.391051,-66.0152098/@-33.2242713,-66.2845622,11z/data=!3m1!4b1!4m8!4m7!1m5!1m1!1s0x95d43954196ca6cd:0x7fc2e3b4d49ecc83!2m2!1d-66.3377522!2d-33.3017267!1m0</span></a></span></p>', 'ESCUELA_Nº_164_y_228_gps2.jpg', '<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">la Escuela N&ordm;228 &ldquo;Gobernador Juan Saa&rdquo; (paraje Algarrobos blancos).</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">La comunidades cuenta con distintos recursos, ya sean educativos, de salud, religiosos y recreativos en cercan&iacute;as. La escuela tiene nivel inicial, primario y comparten espacio f&iacute;sico con escuelas generativas secundarias. es una escuela con plurigrados.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">La mayor&iacute;a de las familias tienen trabajo o planes del gobierno.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">Algunos ni&ntilde;os provienen de familias de escasos recursos a los cuales se trata de ayudar desde la escuela.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">La escuela N&ordm; 164 Maestros Puntanos (</span><span lang=\"es\" style=\"font-family: \'Segoe UI\',sans-serif; color: black;\">ELEODORO LOBOS - SAN LUIS), es una escuela unipersonal, con plurigrado y una matr&iacute;cula aproximada de 20 estudiantes que comparten espacio f&iacute;sico, donde los estudiantes m&aacute;s grandes ayudan a los m&aacute;s peque&ntilde;os. Consta de una sola ordenanza quien se encarga de las actividades correspondientes y brinda la copa de leche. La mayor&iacute;a de los estudiantes viven alejados de la escuela (aproximadamente 10-15 km). En general </span><span lang=\"ES\" style=\"mso-ansi-language: ES;\">las <span style=\"mso-spacerun: yes;\">&nbsp;</span>familias tienen trabajo como empleados en estancias, los padres suelen trasladar y acompa&ntilde;ar a los estudiantes durante las jornadas diarias a fin disminuir gastos de traslados dado que la escuela no cuenta con transporte para los estudiantes</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span lang=\"ES\" style=\"mso-ansi-language: ES;\">Estas escuelas elegidas para desarrollar el proyecto son rurales o con caracter&iacute;sticas de escuelas rurales, donde los estudiantes recorren largas distancias para concurrir al establecimiento educativo a fin de recibir su formaci&oacute;n y donde los recursos econ&oacute;micos son escasos.</span></p>', '', '', '', '<p class=\"MsoNormal\" style=\"text-align: justify; mso-line-height-alt: 12.25pt; margin: .05pt -23.45pt .0001pt 0cm;\"><span lang=\"ES\" style=\"font-size: 13.5pt; font-family: \'Segoe UI\', sans-serif;\">En una primera visita a las Escuelas se prev&eacute; efectuar una reuni&oacute;n con la directora y el cuerpo<span style=\"letter-spacing: .05pt;\">&nbsp;</span>docente a fin de solicitar informaci&oacute;n detallada del n&uacute;mero de alumnos por divisi&oacute;n, horario de<span style=\"letter-spacing: .05pt;\">&nbsp;</span>clases,<span style=\"letter-spacing: -.1pt;\">&nbsp;</span>recreos<span style=\"letter-spacing: -.05pt;\">&nbsp;</span>y<span style=\"letter-spacing: -.1pt;\">&nbsp;</span>coordinar<span style=\"letter-spacing: -.05pt;\">&nbsp;</span>los<span style=\"letter-spacing: -.05pt;\">&nbsp;</span>d&iacute;as<span style=\"letter-spacing: -.1pt;\">&nbsp;</span>y<span style=\"letter-spacing: -.05pt;\">&nbsp;</span>horarios<span style=\"letter-spacing: -.1pt;\">&nbsp;</span>adecuados<span style=\"letter-spacing: -.05pt;\">&nbsp;</span>para<span style=\"letter-spacing: -.05pt;\">&nbsp;</span>desarrollar<span style=\"letter-spacing: -.1pt;\">&nbsp;</span>nuestras<span style=\"letter-spacing: -.05pt;\">&nbsp;</span>actividades.&nbsp;Segunda Visita<u>:&nbsp;</u>se comenzar&aacute; con las actividades previstas&nbsp;realizando una&nbsp;breve explicaci&oacute;n a trav&eacute;s de videos y charlas interactivas sobre los talleres propuestos, luego se proceder&aacute; a la realizaci&oacute;n de los talleres, evaluaremos cual es el conocimiento que tienen los ni&ntilde;os sobre </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; mso-line-height-alt: 12.25pt; margin: .05pt -23.45pt .0001pt 0cm;\"><span lang=\"ES\" style=\"font-size: 13.5pt; font-family: \'Segoe UI\', sans-serif;\">Las ciencias naturales y en base a esto haremos correcciones. Mediante<span style=\"letter-spacing: .05pt;\">&nbsp;estas</span> actividades pretendemos que los ni&ntilde;os sepan aprender en forma interactiva e incorporar nuevos conocimientos.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; mso-line-height-alt: 12.25pt; margin: .05pt -23.45pt .0001pt 0cm;\"><span lang=\"ES\" style=\"font-size: 13.5pt; font-family: \'Segoe UI\', sans-serif;\">En la segunda parte del encuentro se dar&aacute; tambi&eacute;n a trav&eacute;s de videos y charlas una idea de otros talleres y se proceder&aacute; de igual modo</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal; margin: .15pt -23.45pt .0001pt 0cm;\"><span lang=\"ES\" style=\"font-size: 13.5pt; font-family: \'Segoe UI\', sans-serif;\">&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;El personal docente tambi&eacute;n recibir&aacute; su entrenamiento</span></p>\r\n<p><span lang=\"ES\" style=\"font-size: 13.5pt; line-height: 115%; font-family: \'Segoe UI\', sans-serif;\">Estas actividades se repetir&aacute;n en cada una de las escuelas a las que asistiremos ya que las mismas son de modalidad plurigrado</span></p>\r\n<p>&nbsp;</p>\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Actividades</span></strong></td>\r\n<td style=\"width: 31.9395%;\">mes</td>\r\n<td style=\"width: 31.941%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Lugar y destinatarios</span></strong></td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12pt; line-height: 18.4px; font-family: \'Times New Roman\', serif;\">Jugando con pol&iacute;meros y sem&aacute;foro&nbsp;&nbsp;Qu&iacute;mico</span></strong></td>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Abril,&nbsp; junio y septiembre</span></strong></td>\r\n<td style=\"width: 31.941%;\">\r\n<p class=\"MsoNormal\" style=\"line-height: normal; mso-pagination: none; border: none; mso-padding-alt: 31.0pt 31.0pt 31.0pt 31.0pt; mso-border-shadow: yes;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">Escuela N&ordm; </span></strong><span lang=\"ES\">&nbsp;228 y 164</span></p>\r\n<strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Estudiantes y maestros</span></strong></td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Obtenci&oacute;n de pigmentos naturales a partir de verduras&nbsp;</span></strong></td>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Abril,&nbsp; junio y septiembre</span></strong></td>\r\n<td style=\"width: 31.941%;\">\r\n<p class=\"MsoNormal\" style=\"line-height: normal; mso-pagination: none; border: none; mso-padding-alt: 31.0pt 31.0pt 31.0pt 31.0pt; mso-border-shadow: yes;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">Escuela N&ordm; </span></strong><span lang=\"ES\">&nbsp;228 y 164</span></p>\r\n<strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Estudiantes y maestros</span></strong></td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">La qu&iacute;mica en la construcci&oacute;n de una erupci&oacute;n volc&aacute;nica</span></strong></td>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Abril,&nbsp; junio y septiembre</span></strong></td>\r\n<td style=\"width: 31.941%;\">\r\n<p class=\"MsoNormal\" style=\"line-height: normal; mso-pagination: none; border: none; mso-padding-alt: 31.0pt 31.0pt 31.0pt 31.0pt; mso-border-shadow: yes;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">Escuela N&ordm; </span></strong><span lang=\"ES\">&nbsp;228 y 164</span></p>\r\n<strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Estudiantes y maestros</span></strong></td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Bajo la lupa: espumas que cambian de color</span></strong></td>\r\n<td style=\"width: 31.9395%;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Abril,&nbsp; junio y septiembre</span></strong></td>\r\n<td style=\"width: 31.941%;\">\r\n<p class=\"MsoNormal\" style=\"line-height: normal; mso-pagination: none; border: none; mso-padding-alt: 31.0pt 31.0pt 31.0pt 31.0pt; mso-border-shadow: yes;\"><strong><span lang=\"es\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\';\">Escuela N&ordm; </span></strong><span lang=\"ES\">&nbsp;228 y 164</span></p>\r\n<strong><span lang=\"es\" style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: #000A; mso-fareast-language: ES-AR; mso-bidi-language: AR-SA;\">Estudiantes y maestros</span></strong></td>\r\n</tr>\r\n</tbody>\r\n</table>', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'aval_aleodoro_lobos.jpeg', 'peis', 'Pendiente a revisión', 0, 116);
